cat > /tmp/bot-check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { decideWhatsApp as d } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g5-3/bot.mjs';

const T = 1767272400; // webhook timestamp, seconds
const at = (s) => new Date((T + s) * 1000);
const c = (ts, optedIn = true) => ({ optedIn, lastInboundTimestamp: ts });
const H24 = 24 * 3600;

// template: opted in, any window state
assert.deepEqual(d({ type: 'template', contact: c(null) }, at(0)), { allowed: true, reason: null });
assert.deepEqual(d({ type: 'template', contact: c(String(T)) }, at(H24 * 10)), { allowed: true, reason: null });
// opt-in gates everything
assert.equal(d({ type: 'template', contact: c(String(T), false) }, at(60)).reason, 'not_opted_in');
assert.equal(d({ type: 'text', contact: c(String(T), false) }, at(60)).reason, 'not_opted_in');
assert.equal(d({ type: 'text', contact: { lastInboundTimestamp: String(T) } }, at(60)).reason, 'not_opted_in');
// text inside window
assert.deepEqual(d({ type: 'text', contact: c(String(T)) }, at(60)), { allowed: true, reason: null });
assert.deepEqual(d({ type: 'text', contact: c(String(T)) }, at(H24 - 1)), { allowed: true, reason: null });
// text at/after 24h boundary
assert.equal(d({ type: 'text', contact: c(String(T)) }, at(H24)).reason, 'customer_window_closed');
assert.equal(d({ type: 'text', contact: c(String(T)) }, at(H24 + 1)).reason, 'customer_window_closed');
// text never inbound
assert.equal(d({ type: 'text', contact: c(null) }, at(0)).reason, 'no_inbound_message');
// ms value mistaken for seconds
assert.equal(d({ type: 'text', contact: c(String(T * 1000)) }, at(0)).reason, 'invalid_inbound_timestamp');
// malformed
assert.equal(d({ type: 'text', contact: c('abc') }, at(0)).reason, 'invalid_inbound_timestamp');
assert.equal(d({ type: 'text', contact: c(T) }, at(0)).reason, 'invalid_inbound_timestamp');
// unknown type
assert.equal(d({ type: 'image', contact: c(String(T)) }, at(0)).reason, 'unsupported_message_type');
// bad now
assert.throws(() => d({ type: 'text', contact: c(String(T)) }, new Date('x')), TypeError);
console.log('all assertions passed');
EOF
